class Net(nn.Module):
    def __init__(self, width=512, blocks=3):
        super().__init__()
        self.x_emb = nn.Linear(51, width)
        self.c_emb = nn.Sequential(nn.Linear(54, width), nn.GELU(), nn.Linear(width, width))
        self.t_emb = nn.Sequential(nn.Linear(64, width), nn.GELU(), nn.Linear(width, width))
        self.blocks = nn.Sequential(*[Block(width) for _ in range(blocks)])
        self.out = nn.Linear(width, 51)

    def forward(self, x, t, c):
        h = self.x_emb(x) + self.c_emb(c) + self.t_emb(sinusoidal(t))
        return self.out(self.blocks(h))

